CREATE TABLE goods_receipts(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,order_id INTEGER NOT NULL,party_id INTEGER NOT NULL,warehouse_id INTEGER NOT NULL,date TEXT NOT NULL,reference TEXT NOT NULL,snapshot TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),document_id INTEGER,UNIQUE(business_id,id),UNIQUE(business_id,reference),UNIQUE(business_id,document_id),FOREIGN KEY(business_id,order_id) REFERENCES commercial_documents(business_id,id),FOREIGN KEY(business_id,party_id) REFERENCES parties(business_id,id),FOREIGN KEY(business_id,warehouse_id) REFERENCES warehouses(business_id,id),FOREIGN KEY(business_id,document_id) REFERENCES documents(business_id,id));
CREATE INDEX receipts_order ON goods_receipts(business_id,order_id);
CREATE TRIGGER receipts_no_delete BEFORE DELETE ON goods_receipts BEGIN SELECT RAISE(ABORT,'receipts are immutable'); END;
CREATE TRIGGER receipts_no_update BEFORE UPDATE ON goods_receipts WHEN NEW.business_id!=OLD.business_id OR NEW.order_id!=OLD.order_id OR NEW.party_id!=OLD.party_id OR NEW.warehouse_id!=OLD.warehouse_id OR NEW.date!=OLD.date OR NEW.reference!=OLD.reference OR NEW.snapshot!=OLD.snapshot OR NEW.value!=OLD.value OR OLD.document_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'receipts are immutable'); END;
